(ns fastmath.signal.waveform-test
  (:require [fastmath.signal.waveform :as sut]
            [fastmath.signal :as sig]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn]))

;; scipy.signal square / sawtooth (with phase shifts) and Fourier sums, generated by
;; `utils/fastmath/dev/generate_waveform_reference.py` into
;; `test/resources/signal/waveform_reference.edn`: f = 2, phase = 0.1, amplitude = 1.5,
;; t in [-2, 2] (negative time included), no sample at a jump.

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/waveform_reference.edn")))))

(defn- max-diff
  [a b]
  (reduce max 0.0 (map #(Math/abs (- (double %1) (double %2))) a b)))

(def ^:private options {:f 2.0 :phase 0.1 :amplitude 1.5})

(t/deftest waveforms-vs-scipy
  (let [{:keys [t] :as r} @reference]
    (doseq [[k w] {:sine (sut/->sine options)
                   :square (sut/->square (assoc options :duty 0.3))
                   :saw-up (sut/->saw options)
                   :saw-down (sut/->saw (assoc options :up? false))
                   :triangle (sut/->triangle options)
                   :band-limited-square (sut/->band-limited-square (assoc options :bands 7))
                   :band-limited-saw (sut/->band-limited-saw (assoc options :bands 7))
                   :band-limited-triangle (sut/->band-limited-triangle (assoc options :bands 7))}]
      ;; phases up to 4 cycles, sums of 7 sines; measured maximum difference 1.8e-14
      (t/is (<= (max-diff (r k) (map w t)) 1.0e-12) (str k)))))

(t/deftest periodic-for-negative-time
  (doseq [k [:sine :analog-sine :square :saw :analog-saw :triangle :analog-triangle
             :band-limited-square :band-limited-saw :band-limited-triangle]
          :let [w (sig/waveform k {:f 1.0 :phase 0.13 :duty 0.3})]]
    (t/is (every? (fn [t] (< (Math/abs (- (w t) (w (+ t 1.0)))) 1.0e-12))
                  (map #(- (* 0.0371 %) 3.0) (range 100)))
          (str k " f(t) = f(t+1) for t in [-3, 0.7]"))))

(t/deftest phase-function
  (t/testing ":f as a function is the phase in cycles"
    (let [w (sut/->sine {:f (fn [t] (* 3.0 t t))})]
      (t/is (< (Math/abs (- (Math/sin (* 2.0 Math/PI 3.0 0.49)) (w 0.7))) 1e-15)))))

(t/deftest polyblep
  (let [samples (take 4410 #_{:clj-kondo/ignore [:unresolved-var]} (sut/polyblep-hyptri {:f 441.0 :fs 44100.0}))
        mean (/ (reduce + samples) (count samples))]
    (t/is (< (Math/abs mean) 0.005) "mean -0.0015 measured (offset -1 as Tale's poly_hyptri; was -0.31 with -1.313)")
    (t/is (<= (reduce max samples) 1.32))
    (t/is (>= (reduce min samples) -0.7))))

(t/deftest guards
  (t/is (thrown? clojure.lang.ExceptionInfo (sig/waveform :pulse))))
